static class Use
  public static method Drain(cb: () -> IEnumerable<int>)
    for var x in cb() do                   // cb() keyed on its declared return: an owned frame
      Console.WriteLine($"{x}");
    end;                                   // the loop's using var __source disposes it
  end Drain;
  public static method Run()
    using var xs: Array<int> := [1, 2, 3];
    var h := new Holder<IEnumerable<int>>();
    h.Reg := Drain;                        // capture-free static reference at a function-typed holder
    h.Lend(xs);                            // Drain disposes `xs`, which Run owns
    xs.Add(4);                             // use after disposal (checked mode: DisposedAccessException)
  end Run;
end Use;

